"use strict";(self.webpackChunktik_space=self.webpackChunktik_space||[]).push([["857"],{21567(e){e.exports=JSON.parse('{"tag":{"label":"Tier 2 \u2014 Distributed thinking","permalink":"/vi/docs/tags/tier-2-distributed","description":"What changes once a call can cross a network and fail halfway.","allTagsPath":"/vi/docs/tags","count":26,"items":[{"id":"production-patterns/api-contracts","title":"API Contracts & Versioning","description":"Rule: an API is not an endpoint, it is a promise you cannot withdraw. Internal code can be","permalink":"/vi/docs/production-patterns/api-contracts"},{"id":"production-patterns/api-resource-modeling","title":"API Resource Modeling","description":"Rule: an API manages the lifecycle of resources; it does not expose your actions or your tables.","permalink":"/vi/docs/production-patterns/api-resource-modeling"},{"id":"production-patterns/api-async-operations","title":"Async & Long-Running Operations","description":"Rule: when the answer does not exist yet, do not pretend the request can return it. Model the","permalink":"/vi/docs/production-patterns/api-async-operations"},{"id":"how-it-works/distributed-systems/availability-patterns","title":"Availability Patterns","description":"Availability is arithmetic before it is architecture. The arithmetic is worth doing first, because","permalink":"/vi/docs/how-it-works/distributed-systems/availability-patterns"},{"id":"how-it-works/estimation/back-of-the-envelope","title":"Back-of-the-Envelope Estimation","description":"An estimate is not a prediction. It is a filter: a way to find out, in two minutes and before","permalink":"/vi/docs/how-it-works/estimation/back-of-the-envelope"},{"id":"production-patterns/replica-placement-and-quorums","title":"B\u1ED1 tr\xed replica & Quorum","description":"Quy t\u1EAFc: \u0111\u1ED9 b\u1EC1n d\u1EEF li\u1EC7u kh\xf4ng ph\u1EA3i l\xe0 s\u1ED1 b\u1EA3n sao b\u1EA1n \u0111\xe3 c\u1EA5u h\xecnh \u2014 m\xe0 l\xe0 s\u1ED1 b\u1EA3n sao ph\u1EA3i x\xe1c nh\u1EADn","permalink":"/vi/docs/production-patterns/replica-placement-and-quorums"},{"id":"how-it-works/distributed-systems/cap-theorem","title":"CAP Theorem","description":"CAP is the most cited and most misquoted result in distributed systems. The popular version \u2014","permalink":"/vi/docs/how-it-works/distributed-systems/cap-theorem"},{"id":"production-patterns/circuit-breakers-and-bulkheads","title":"Circuit Breakers & Bulkheads","description":"Rule: a dying dependency needs to be isolated, not attacked with more requests. Breakers stop","permalink":"/vi/docs/production-patterns/circuit-breakers-and-bulkheads"},{"id":"how-it-works/distributed-systems/consistency-models","title":"Consistency Models","description":"A consistency model is a contract about what a read is allowed to return. It is not a quality","permalink":"/vi/docs/how-it-works/distributed-systems/consistency-models"},{"id":"production-patterns/designing-for-failure","title":"Designing for Failure","description":"Rule: failure is the default state, not the exception. Large systems are not designed for the","permalink":"/vi/docs/production-patterns/designing-for-failure"},{"id":"production-patterns/distributed-transactions","title":"Distributed Transactions","description":"Rule: ACID stops at the database boundary, and \\"localhost is a great lie.\\" Across services you","permalink":"/vi/docs/production-patterns/distributed-transactions"},{"id":"production-patterns/consensus-and-leader-election","title":"\u0110\u1ED3ng thu\u1EADn & B\u1EA7u leader","description":"Quy t\u1EAFc: \u0111\u1ED3ng thu\u1EADn \u0111\xf2i h\u1ECFi \u0111a s\u1ED1, kh\xf4ng ph\u1EA3i m\u1ED9t \u0111i\u1EC1u ph\u1ED1i vi\xean. B\u1EA5t k\u1EF3 c\u01A1 ch\u1EBF n\xe0o \u0111\u1EC3 m\u1ED9t node","permalink":"/vi/docs/production-patterns/consensus-and-leader-election"},{"id":"production-patterns/event-replay-and-projection-rebuild","title":"Event Replay & Projection Rebuild","description":"Rule: a replay recomputes state; it must never re-execute the past. Rebuilding a projection is","permalink":"/vi/docs/production-patterns/event-replay-and-projection-rebuild"},{"id":"production-patterns/event-schema-evolution","title":"Event Schema Evolution","description":"Rule: every event version ever written is a format you must read, with its original meaning, for","permalink":"/vi/docs/production-patterns/event-schema-evolution"},{"id":"production-patterns/event-sourcing-and-cqrs","title":"Event Sourcing, Snapshots & CQRS","description":"Rule: storing state answers \\"what is it now\\"; storing events answers \\"how did it get there\\".","permalink":"/vi/docs/production-patterns/event-sourcing-and-cqrs"},{"id":"how-it-works/estimation/latency-numbers","title":"Latency Numbers","description":"The point of knowing these is not recall for its own sake. It is being able to reject a design in","permalink":"/vi/docs/how-it-works/estimation/latency-numbers"},{"id":"production-patterns/api-list-endpoints","title":"List Endpoints: Pagination, Filtering & Sorting","description":"Rule: a list endpoint is a cost-control mechanism first and a feature second. Unbounded","permalink":"/vi/docs/production-patterns/api-list-endpoints"},{"id":"production-patterns/multi-region-failover","title":"Multi-Region Failover","description":"Rule: a second region is a disaster plan only if three things were decided before the disaster \u2014","permalink":"/vi/docs/production-patterns/multi-region-failover"},{"id":"how-it-works/consensus/raft","title":"Raft","description":"* Network messages can be delayed, reordered, or lost.","permalink":"/vi/docs/how-it-works/consensus/raft"},{"id":"production-patterns/rate-limiting","title":"Rate Limiting","description":"Rule: without a limit, one client\'s mistake becomes everyone\'s outage. A rate limit is not","permalink":"/vi/docs/production-patterns/rate-limiting"},{"id":"production-patterns/replication-and-sharding","title":"Replication & Sharding","description":"Rule: a replica is a different point in time, and a shard key is a decision you cannot undo.","permalink":"/vi/docs/production-patterns/replication-and-sharding"},{"id":"production-patterns/session-consistency","title":"Session Consistency: Read-Your-Writes, Monotonic Reads & Causal Order","description":"Rule: \\"eventually consistent\\" is not a promise you can hand a user. Each read path has to","permalink":"/vi/docs/production-patterns/session-consistency"},{"id":"production-patterns/network-and-latency","title":"The Network & Latency","description":"Rule: a healthy service plus a healthy service does not equal a healthy system. The network","permalink":"/vi/docs/production-patterns/network-and-latency"},{"id":"production-patterns/timeouts-and-retries","title":"Timeouts & Retries","description":"Rule: retry without idempotency is not error handling \u2014 it is a bug. And a retry that fires","permalink":"/vi/docs/production-patterns/timeouts-and-retries"},{"id":"how-it-works/consensus/viewstamped-replication","title":"Viewstamped Replication (VSR)","description":"VSR is a state machine replication protocol designed to keep a group of replicas consistent even when some fail. It","permalink":"/vi/docs/how-it-works/consensus/viewstamped-replication"},{"id":"production-patterns/webhook-provider-design","title":"Webhook Provider Design","description":"Rule: sending a webhook once is not delivering it. Without signatures, retries, and a way to","permalink":"/vi/docs/production-patterns/webhook-provider-design"}],"unlisted":false}}')}}]);